class DHTManager {
private:
    DHT _dht;
    float _lastTemperature;
    float _lastHumidity;
    bool _hasValidData;
public:
    DHTManager(uint8_t pin, uint8_t type) : _dht(pin, type) {}
    void begin() { _dht.begin(); _lastTemperature = NAN; _lastHumidity = NAN; _hasValidData = false; }
    void update() {
        float temp = _dht.readTemperature();
        float hum = _dht.readHumidity();
        if (!isnan(temp) && !isnan(hum)) {
            _lastTemperature = temp; _lastHumidity = hum; _hasValidData = true;
        } else { _hasValidData = false; Log.error(F("Ошибка чтения DHT22")); }
    }
    float getTemperature() const { return _lastTemperature; }
    float getHumidity() const { return _lastHumidity; }
    bool hasValidData() const { return _hasValidData; }
};

