void selfDiagnosis() {
    if (!isValidTemp(outside_temp)) client.publish(error_topic, "Ошибка DS18B20 (наружная)");
    if (!isValidTemp(supply_temp)) client.publish(error_topic, "Ошибка DS18B20 (подача)");
