void managePump(float supplyTemp) {
    static bool was_pump_on = false;
    bool currentRelayState = digitalRead(PIN_PUMP_RELAY) == LOW;
    if (supplyTemp >= SUPPLY_TARGET_TEMP && !was_pump_on) {
        was_pump_on = true; digitalWrite(PIN_PUMP_RELAY, LOW); 
    } else if (supplyTemp <= SUPPLY_TARGET_TEMP - HYSTERESIS && was_pump_on) {
        was_pump_on = false; digitalWrite(PIN_PUMP_RELAY, HIGH); 
    }
}

void monitorBoilerPerformance(float supplyTemp) {
    float currentSmokeTemp = thermoCouple.readCelsius();
    float airTemp = dhtManager.getTemperature();
    smoke_temp = currentSmokeTemp;

    if (currentSmokeTemp >= 120.0) {
        SupplyOutput = SERVO_MIN_ANGLE; myServo.write(SupplyOutput);
        boiler_is_active = false;
        if (!boiler_safety_lockout) {
            Log.error(F("АВАРИЯ: Дым %.1f°C! Заслонка закрыта."), currentSmokeTemp);
            client.publish(error_topic, "Overheat Smoke");
        }
        boiler_safety_lockout = true; return;
    }

    if (boiler_safety_lockout && currentSmokeTemp < 90.0) {
        Log.notice(F("СИСТЕМА: Авария снята. Дым остыл до %.1f°C"), currentSmokeTemp);
        boiler_safety_lockout = false;
        SupplyOutput = SAFE_START_ANGLE; myServo.write((int)SupplyOutput);
        delay(500);
    }

    if (boiler_safety_lockout) {
        SupplyOutput = constrain(SupplyOutput, SERVO_MIN_ANGLE, 30); 
        myServo.write((int)SupplyOutput); return;
    }

    if (airTemp >= AIR_TARGET_TEMP) {
        SupplyOutput = SERVO_MIN_ANGLE; myServo.write(SupplyOutput);
        boiler_is_active = false; return;
    }

    if (supplyTemp < SUPPLY_TARGET_TEMP) {
        controlServo(); boiler_is_active = true;
    } else {
        SupplyOutput = 10.0; myServo.write((int)SupplyOutput);
        boiler_is_active = false;
    }
}

