    Log.verbose(F("⬇️ Получено сообщение: Topic='%s', Value='%s'"), receivedTopic.c_str(), message.c_str());
    double prevSupplyTemp = SUPPLY_TARGET_TEMP; double prevAirTemp = AIR_TARGET_TEMP;
    if (receivedTopic.equals(supply_target_temp_topic)) {
        updateTargetTemperature(receivedTopic, message, SUPPLY_TARGET_TEMP, 15.0, 70.0);
        notifyTargetChange(receivedTopic, prevSupplyTemp, SUPPLY_TARGET_TEMP);
    } else if (receivedTopic.equals(air_target_temp_topic)) {
        updateTargetTemperature(receivedTopic, message, AIR_TARGET_TEMP, 5.0, 25.0);
        notifyTargetChange(receivedTopic, prevAirTemp, AIR_TARGET_TEMP);
    }
}

