void mainTask(void *pvParameters) {
     TickType_t xLastWakeTime = xTaskGetTickCount(); const TickType_t xFrequency = pdMS_TO_TICKS(10000); 
     unsigned long lastAntiSeize = 0;
     for (;;) { 
         esp_task_wdt_reset(); 
         monitorBoilerPerformance(supply_temp); managePump(supply_temp);

         // === АНТИБЛОКИРОВКА НАСОСА (РАЗ В НЕДЕЛЮ) ===
         if (millis() - lastAntiSeize > PUMP_ANTI_SEIZE_INTERVAL) {
             Log.notice(F("СИСТЕМА: Анти-блокировка насоса (проворот)"));
             digitalWrite(PIN_PUMP_RELAY, LOW);
             vTaskDelay(pdMS_TO_TICKS(60000)); // Держим 1 минуту
             digitalWrite(PIN_PUMP_RELAY, HIGH);
             lastAntiSeize = millis();
             continue; // Пропускаем этот цикл, чтобы не сбить тайминги
         }

         sensorOutside.requestTemperatures(); sensorSupply.requestTemperatures(); sensorReturn.requestTemperatures();
         vTaskDelay(pdMS_TO_TICKS(800)); 
         outside_temp = sensorOutside.getTempCByIndex(0); supply_temp = sensorSupply.getTempCByIndex(0); return_temp = sensorReturn.getTempCByIndex(0);
         smoke_temp = thermoCouple.readCelsius(); publishSensorValues(); selfDiagnosis();
         vTaskDelayUntil(&xLastWakeTime, xFrequency); 
     }
}

