void reconnect() {
    while (!client.connected()) {
        Log.notice(F("Попытка подключения к MQTT...")); String clientId = "ESP32-Heating-"; clientId += String(random(0xffff), HEX);
        if (client.connect(clientId.c_str(), mqtt_user, mqtt_password)) {
            Log.notice(F("MQTT подключен! ID: %s"), clientId.c_str()); client.subscribe(supply_target_temp_topic); client.subscribe(air_target_temp_topic);
        } else { Log.error(F("Ошибка MQTT, rc=%d. Попытка через 5 сек"), client.state()); vTaskDelay(pdMS_TO_TICKS(5000)); }
    }
}

void publishSensorValues() {
    if (!client.connected()) return; char buf[8];
    if (isValidTemp(outside_temp)) { dtostrf(outside_temp, 6, 2, buf); client.publish(external_temp_topic, buf); }
    if (isValidTemp(supply_temp)) { dtostrf(supply_temp, 6, 2, buf); client.publish(supply_temp_topic, buf); }
    if (isValidTemp(return_temp)) { dtostrf(return_temp, 6, 2, buf); client.publish(return_temp_topic, buf); }
    if (isValidTemp(smoke_temp)) { dtostrf(smoke_temp, 6, 2, buf); client.publish(smoke_temp_topic, buf); }
    if (dhtManager.hasValidData()) { dtostrf(dht_temp, 6, 2, buf); client.publish(dht_temp_topic, buf); dtostrf(dht_hum, 6, 2, buf); client.publish(dht_hum_topic, buf); }
    client.publish(boiler_status_topic, boiler_is_active ? "1" : "0");
}

