void loadSettingsFromNVS() { Preferences prefs; if(prefs.begin("heater_cfg", true)) { SUPPLY_TARGET_TEMP = prefs.getDouble("sup_tgt", 35.0); AIR_TARGET_TEMP = prefs.getDouble("air_tgt", 15.0); prefs.end(); } }
void saveSettingsToNVS(double supplyTemp, double airTemp) { Preferences prefs; if(prefs.begin("heater_cfg", false)) { prefs.putDouble("sup_tgt", supplyTemp); prefs.putDouble("air_tgt", airTemp); prefs.end(); } }

bool validateTargetValue(const String& value, double minVal, double maxVal) { double val = value.toDouble(); return (val >= minVal && val <= maxVal); }
void updateTargetTemperature(String topic, String value, double& targetVar, double minVal, double maxVal) {
    if (validateTargetValue(value, minVal, maxVal)) { targetVar = value.toDouble(); Log.notice(F("✅ Новая уставка: %s = %.1f"), topic.c_str(), targetVar); saveSettingsToNVS(SUPPLY_TARGET_TEMP, AIR_TARGET_TEMP); }
    else { Log.error(F("❌ Неверное значение целевой температуры: %s"), value.c_str()); } }
void notifyTargetChange(String topic, double oldValue, double newValue) {
    if (oldValue != newValue) { char buf[8]; dtostrf(newValue, 6, 2, buf); client.publish(topic.c_str(), buf); } }

void loop() {}
